package cx.m42.unitool

import cx.m42.superizer.host.SuperizerBuilder

/**
 * The apps that are in the build only when their module is (.ai-notes/app-learn D642, D673): every app
 * of the submodule `external/app-learn` (Learning English, books), which a plain clone leaves empty.
 * Common code cannot name a class that may not exist, so the body is generated by
 * `:composeApp:generateOptionalApps` when the submodule is there, and is `src/optional/none/` otherwise.
 * The web build always gets `none/` (D646): those apps have no wasmJs target.
 */
internal expect fun SuperizerBuilder.registerOptionalApps()
